/**
 * LEAD-DB bulk loader — import a large CSV or JSON file of leads into a named
 * EmailList, server-side, using the SAME idempotent dedup/ingest logic as the
 * admin importer (lib/coldemail/import.ts + lib/coldemail/lead-store.ts). Use this
 * instead of the web importer for big files (tens of thousands of rows) — there's
 * no request timeout here.
 *
 * IDEMPOTENT: re-running the same file inserts 0 (all rows match existing and are
 * updated in place). DEAD/suppressed contacts are never resurrected.
 *
 * Usage:
 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Q3 prospects"
 *   npx tsx scripts/import-leads.ts --file leads.json --list-id <listId> --consent
 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Cold UK" --create-list
 *
 * Flags:
 *   --file <path>        CSV or JSON file (JSON = array of objects; keys use the
 *                        same header names/aliases as CSV). Required.
 *   --list <name>        Target list by name. Errors if ambiguous/absent unless
 *                        --create-list is given.
 *   --list-id <id>       Target list by id (takes precedence over --list).
 *   --create-list        Create the list (by --list name) if it doesn't exist.
 *   --consent            Record a LEGITIMATE_INTEREST consent row for each NEW contact.
 *   --dry-run            Parse + report row counts only; write nothing.
 *
 * CSV headers spec: see docs/DOCUMENTATION.md (Lead database → Import). Minimum: an
 * `email` column. Everything else (name, fullName, title, website, phone, city, …)
 * is optional and mapped through IMPORT_HEADER_ALIASES.
 */
import { readFileSync } from "node:fs";
import { db } from "../lib/db";
import {
  ingestLeads,
  parseCsv,
  csvToLeadRows,
  IMPORT_HEADER_ALIASES,
  type LeadRow,
} from "../lib/coldemail/import";
import { prismaLeadStore } from "../lib/coldemail/lead-store";

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(`--${name}`);
  return i !== -1 ? process.argv[i + 1] : undefined;
}
function flag(name: string): boolean {
  return process.argv.includes(`--${name}`);
}

/** Map an arbitrary JSON object's keys onto canonical LeadRow fields via the aliases. */
function jsonObjToLeadRow(obj: Record<string, unknown>): LeadRow {
  const lead: LeadRow = {};
  for (const [k, v] of Object.entries(obj)) {
    const field = IMPORT_HEADER_ALIASES[k.trim().toLowerCase()];
    if (field && v != null) lead[field] = String(v).trim();
  }
  return lead;
}

async function main(): Promise<void> {
  const filePath = arg("file");
  if (!filePath) {
    console.error("ERROR: --file <path> is required. See the header of this script for usage.");
    process.exit(1);
  }

  const listName = arg("list");
  const listIdArg = arg("list-id");
  const createList = flag("create-list");
  const recordConsent = flag("consent");
  const dryRun = flag("dry-run");

  // ---- Load + parse the file into LeadRow[] ----
  const raw = readFileSync(filePath, "utf8");
  let rows: LeadRow[];
  if (filePath.toLowerCase().endsWith(".json")) {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) throw new Error("JSON file must be an array of lead objects.");
    rows = parsed.map((o) => jsonObjToLeadRow(o as Record<string, unknown>));
  } else {
    const { headers, rows: csvRows } = parseCsv(raw);
    if (headers.length === 0) throw new Error("Could not parse a header row from the CSV.");
    rows = csvToLeadRows(headers, csvRows);
  }
  console.log(`Parsed ${rows.length} row(s) from ${filePath}.`);

  if (dryRun) {
    console.log("--dry-run: no changes written.");
    await db.$disconnect();
    return;
  }

  // ---- Resolve the target list ----
  let listId: string | null = null;
  if (listIdArg) {
    const list = await db.emailList.findUnique({ where: { id: listIdArg }, select: { id: true } });
    if (!list) throw new Error(`No list with id ${listIdArg}.`);
    listId = list.id;
  } else if (listName) {
    const matches = await db.emailList.findMany({ where: { name: listName }, select: { id: true } });
    if (matches.length === 1) listId = matches[0].id;
    else if (matches.length === 0) {
      if (!createList) throw new Error(`No list named "${listName}". Pass --create-list to create it.`);
      const created = await db.emailList.create({ data: { name: listName }, select: { id: true } });
      listId = created.id;
      console.log(`Created list "${listName}" (${listId}).`);
    } else {
      throw new Error(`"${listName}" is ambiguous (${matches.length} lists). Use --list-id.`);
    }
  } else {
    console.log("No --list/--list-id given — importing into the lead DB without list assignment.");
  }

  // ---- Ingest via the shared, idempotent core ----
  const batch = await db.importBatch.create({
    data: { name: `Script import ${new Date().toISOString().slice(0, 16)}`, source: "script", listId },
    select: { id: true },
  });

  const result = await ingestLeads(rows, {
    store: prismaLeadStore("script"),
    listId,
    batchId: batch.id,
    recordConsent,
    consentSource: "script import",
  });

  await db.importBatch.update({
    where: { id: batch.id },
    data: {
      totalRows: result.totalRows,
      inserted: result.inserted,
      updated: result.updated,
      skippedDead: result.skippedDead,
      skippedDup: result.skippedDup,
      skippedInvalid: result.skippedInvalid,
    },
  });

  console.log("Import complete:");
  console.log(`  inserted (new):          ${result.inserted}`);
  console.log(`  updated (existing):      ${result.updated}`);
  console.log(`  skipped dead/suppressed: ${result.skippedDead}`);
  console.log(`  skipped in-file dupes:   ${result.skippedDup}`);
  console.log(`  skipped invalid (no email): ${result.skippedInvalid}`);
  console.log(`  batch id: ${batch.id}`);

  await db.$disconnect();
}

main().catch(async (err) => {
  console.error("Import failed:", err?.message ?? err);
  await db.$disconnect().catch(() => null);
  process.exit(1);
});

1	// Cold Email Engine — LEAD-DATABASE bulk import + continuous ingestion core.
2	//
3	// PURE ORCHESTRATION over an injected `LeadStore` so the exact same idempotent
4	// dedup/ingest logic runs from (a) the admin server action, (b) the operator CLI
5	// script scripts/import-leads.ts, and (c) the tests (with an in-memory store, no
6	// DB). The store is the ONLY thing that touches Prisma.
7	//
8	// IDEMPOTENCY + HYGIENE GUARANTEES:
9	//   - Dedup by NORMALIZED email (primary key of a lead). A repeat of an email
10	//     already seen earlier in the same file is skipped (skippedDup).
11	//   - An incoming email that matches an existing contact UPDATES it (fills blanks,
12	//     re-adds to the target list) — never inserts a duplicate. So a re-import of
13	//     the same file inserts 0.
14	//   - An incoming email that matches an existing DEAD or globally-SUPPRESSED
15	//     contact is NOT resurrected (skippedDead) — no update, no re-add to a list.
16	//   - A brand-new email that is already on the global suppression list is refused
17	//     (skippedDead) — we never add a suppressed address.
18	//   - Secondary signal: phone/website(domain) are recorded on the Business but the
19	//     dedup key is always the email (the only reliable per-person identifier).
20	
21	import { normalizeEmail, emailDomain, normalizeDomain } from "@/lib/coldemail/compliance";
22	import { isDeadStatus, type EmailStatusValue } from "@/lib/coldemail/leaddb";
23	
24	// ---------------------------------------------------------------------------
25	// Row model + header spec
26	// ---------------------------------------------------------------------------
27	
28	/**
29	 * Canonical field names an import row can carry. The CSV header row is mapped onto
30	 * these via IMPORT_HEADER_ALIASES; a JSON array uses these keys directly.
31	 */
32	export type LeadRow = {
33	  email?: string;
34	  fullName?: string;
35	  title?: string;
36	  // Business fields:
37	  name?: string; // business name
38	  category?: string;
39	  businessType?: string;
40	  website?: string;
41	  phone?: string;
42	  addressLine?: string;
43	  city?: string;
44	  region?: string;
45	  country?: string;
46	  companySize?: string;
47	};
48	
49	/**
50	 * Header alias → canonical field. Superset of the legacy Businesses importer so old
51	 * files keep working. Keys are compared lower-cased + trimmed.
52	 */
53	export const IMPORT_HEADER_ALIASES: Record<string, keyof LeadRow> = {
54	  email: "email",
55	  "email address": "email",
56	  "e-mail": "email",
57	  contactemail: "email",
58	  fullname: "fullName",
59	  "full name": "fullName",
60	  contact: "fullName",
61	  contactname: "fullName",
62	  "contact name": "fullName",
63	  name2: "fullName",
64	  person: "fullName",
65	  title: "title",
66	  role: "title",
67	  jobtitle: "title",
68	  "job title": "title",
69	  name: "name",
70	  business: "name",
71	  company: "name",
72	  "company name": "name",
73	  organization: "name",
74	  category: "category",
75	  industry: "category",
76	  type: "businessType",
77	  businesstype: "businessType",
78	  website: "website",
79	  url: "website",
80	  domain: "website",
81	  phone: "phone",
82	  tel: "phone",
83	  telephone: "phone",
84	  address: "addressLine",
85	  addressline: "addressLine",
86	  street: "addressLine",
87	  city: "city",
88	  region: "region",
89	  state: "region",
90	  province: "region",
91	  country: "country",
92	  size: "companySize",
93	  companysize: "companySize",
94	  employees: "companySize",
95	};
96	
97	/** Human-facing spec for the import UI + docs (defined in a client-safe module). */
98	export { IMPORT_HEADERS_SPEC } from "./import-spec";
99	
100	// ---------------------------------------------------------------------------
101	// CSV parsing (RFC-4180-ish: quoted fields, embedded commas/newlines, "" escape).
102	// ---------------------------------------------------------------------------
103	
104	export function parseCsv(text: string): { headers: string[]; rows: string[][] } {
105	  const records: string[][] = [];
106	  let field = "";
107	  let row: string[] = [];
108	  let inQuotes = false;
109	  const src = (text ?? "").replace(/\r\n?/g, "\n");
110	
111	  for (let i = 0; i < src.length; i++) {
112	    const c = src[i];
113	    if (inQuotes) {
114	      if (c === '"') {
115	        if (src[i + 1] === '"') {
116	          field += '"';
117	          i++;
118	        } else {
119	          inQuotes = false;
120	        }
121	      } else {
122	        field += c;
123	      }
124	    } else if (c === '"') {
125	      inQuotes = true;
126	    } else if (c === ",") {
127	      row.push(field);
128	      field = "";
129	    } else if (c === "\n") {
130	      row.push(field);
131	      records.push(row);
132	      row = [];
133	      field = "";
134	    } else {
135	      field += c;
136	    }
137	  }
138	  if (field.length > 0 || row.length > 0) {
139	    row.push(field);
140	    records.push(row);
141	  }
142	
143	  const nonEmpty = records.filter((r) => r.some((f) => f.trim() !== ""));
144	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
145	  const headers = nonEmpty[0].map((h) => h.trim());
146	  return { headers, rows: nonEmpty.slice(1) };
147	}
148	
149	/** Map a parsed CSV (headers + rows) to canonical LeadRow objects. */
150	export function csvToLeadRows(headers: string[], rows: string[][]): LeadRow[] {
151	  const cols = headers.map((h) => IMPORT_HEADER_ALIASES[h.trim().toLowerCase()] ?? null);
152	  return rows.map((r) => {
153	    const lead: LeadRow = {};
154	    cols.forEach((field, i) => {
155	      if (field) lead[field] = (r[i] ?? "").trim();
156	    });
157	    return lead;
158	  });
159	}
160	
161	// ---------------------------------------------------------------------------
162	// Normalisation + validation of a single lead row
163	// ---------------------------------------------------------------------------
164	
165	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
166	
167	export type NormalizedLead = {
168	  email: string;
169	  domain: string;
170	  fullName: string;
171	  title: string;
172	  business: {
173	    name: string;
174	    category: string;
175	    businessType: string;
176	    website: string;
177	    phone: string;
178	    addressLine: string;
179	    city: string;
180	    region: string;
181	    country: string;
182	    companySize: string;
183	  };
184	};
185	
186	/**
187	 * Normalise + validate a row. Returns null when there is no usable email — the lead
188	 * database is keyed on emailable people, so an email-less row can't be a lead. The
189	 * business name falls back to the email domain so a name-less row still imports.
190	 */
191	export function normalizeLeadRow(raw: LeadRow): NormalizedLead | null {
192	  const email = normalizeEmail(raw.email);
193	  if (!email || !EMAIL_RE.test(email)) return null;
194	  const domain = emailDomain(email);
195	  const website = (raw.website ?? "").trim();
196	  const name = (raw.name ?? "").trim() || domain;
197	  return {
198	    email,
199	    domain,
200	    fullName: (raw.fullName ?? "").trim().slice(0, 160),
201	    title: (raw.title ?? "").trim().slice(0, 120),
202	    business: {
203	      name: name.slice(0, 160),
204	      category: (raw.category ?? "").trim().slice(0, 120),
205	      businessType: (raw.businessType ?? "").trim().slice(0, 120),
206	      website: website ? normalizeDomain(website).slice(0, 200) || website.slice(0, 200) : "",
207	      phone: (raw.phone ?? "").trim().slice(0, 60),
208	      addressLine: (raw.addressLine ?? "").trim().slice(0, 200),
209	      city: (raw.city ?? "").trim().slice(0, 120),
210	      region: (raw.region ?? "").trim().slice(0, 120),
211	      country: (raw.country ?? "").trim().slice(0, 120),
212	      companySize: (raw.companySize ?? "").trim().slice(0, 60),
213	    },
214	  };
215	}
216	
217	// ---------------------------------------------------------------------------
218	// The store the ingest orchestrator drives (Prisma in prod, a fake in tests)
219	// ---------------------------------------------------------------------------
220	
221	export type ExistingContact = {
222	  id: string;
223	  businessId: string;
224	  emailStatus: EmailStatusValue | string;
225	  fullName: string;
226	  title: string;
227	};
228	
229	export interface LeadStore {
230	  /** Find a contact by NORMALIZED email, or null. */
231	  findContact(email: string): Promise<ExistingContact | null>;
232	  /** Is this email (or its domain) on the global suppression list? */
233	  isSuppressed(email: string): Promise<boolean>;
234	  /** Create a Business, return its id. */
235	  createBusiness(data: NormalizedLead["business"], batchId: string | null): Promise<string>;
236	  /** Create a Contact (status UNVERIFIED), return its id. */
237	  createContact(
238	    input: { businessId: string; email: string; fullName: string; title: string },
239	    batchId: string | null,
240	  ): Promise<string>;
241	  /** Fill blank fields on an existing contact (never overwrite non-empty). */
242	  updateContact(
243	    id: string,
244	    input: { fullName?: string; title?: string },
245	    batchId: string | null,
246	  ): Promise<void>;
247	  /** Add a contact to a list, idempotently (no-op if already a member). */
248	  addToList(contactId: string, listId: string): Promise<void>;
249	  /** Record a lawful-basis consent row for a newly-created contact. */
250	  recordConsent(contactId: string, source: string): Promise<void>;
251	}
252	
253	// ---------------------------------------------------------------------------
254	// The ingest orchestrator
255	// ---------------------------------------------------------------------------
256	
257	export type ImportResult = {
258	  totalRows: number;
259	  inserted: number;
260	  updated: number;
261	  skippedDead: number;
262	  skippedDup: number;
263	  skippedInvalid: number;
264	  contactIds: string[];
265	};
266	
267	export type IngestOptions = {
268	  store: LeadStore;
269	  listId: string | null;
270	  batchId?: string | null;
271	  recordConsent?: boolean;
272	  consentSource?: string;
273	};
274	
275	/**
276	 * Ingest normalized-or-raw rows into the lead database, idempotently.
277	 *
278	 * For each row (see file header for the full guarantee set): validate → dedup
279	 * within the file → look up the existing contact → refuse dead/suppressed →
280	 * update-or-insert → add to the target list. Returns the batch tally.
281	 */
282	export async function ingestLeads(rows: LeadRow[], opts: IngestOptions): Promise<ImportResult> {
283	  const { store, listId, batchId = null, recordConsent = false, consentSource = "bulk import" } = opts;
284	  const result: ImportResult = {
285	    totalRows: rows.length,
286	    inserted: 0,
287	    updated: 0,
288	    skippedDead: 0,
289	    skippedDup: 0,
290	    skippedInvalid: 0,
291	    contactIds: [],
292	  };
293	
294	  const seen = new Set<string>(); // in-file dedup by normalized email
295	
296	  for (const raw of rows) {
297	    const lead = normalizeLeadRow(raw);
298	    if (!lead) {
299	      result.skippedInvalid++;
300	      continue;
301	    }
302	    if (seen.has(lead.email)) {
303	      result.skippedDup++;
304	      continue;
305	    }
306	    seen.add(lead.email);
307	
308	    const existing = await store.findContact(lead.email);
309	
310	    if (existing) {
311	      // NEVER resurrect a dead/suppressed contact.
312	      if (isDeadStatus(existing.emailStatus) || (await store.isSuppressed(lead.email))) {
313	        result.skippedDead++;
314	        continue;
315	      }
316	      // Update in place (fill blanks only) + re-add to the list. No duplicate row.
317	      await store.updateContact(
318	        existing.id,
319	        {
320	          fullName: existing.fullName ? undefined : lead.fullName || undefined,
321	          title: existing.title ? undefined : lead.title || undefined,
322	        },
323	        batchId,
324	      );
325	      if (listId) await store.addToList(existing.id, listId);
326	      result.updated++;
327	      result.contactIds.push(existing.id);
328	      continue;
329	    }
330	
331	    // Brand-new email: refuse if it's already globally suppressed (opted-out before
332	    // the contact row existed) — we never add a suppressed address.
333	    if (await store.isSuppressed(lead.email)) {
334	      result.skippedDead++;
335	      continue;
336	    }
337	
338	    const businessId = await store.createBusiness(lead.business, batchId);
339	    const contactId = await store.createContact(
340	      { businessId, email: lead.email, fullName: lead.fullName, title: lead.title },
341	      batchId,
342	    );
343	    if (listId) await store.addToList(contactId, listId);
344	    if (recordConsent) await store.recordConsent(contactId, consentSource);
345	    result.inserted++;
346	    result.contactIds.push(contactId);
347	  }
348	
349	  return result;
350	}
