test("import idempotency: re-importing the same file inserts 0 (all updated)", async () => {
  const { store } = makeFakeStore();
  const rows = [
    { email: "a@x.com", name: "A", fullName: "Ann" },
    { email: "b@x.com", name: "B", fullName: "Bob" },
  ];
  const first = await ingestLeads(rows, { store, listId: "list1" });
  assert.equal(first.inserted, 2);
  assert.equal(first.updated, 0);

  const second = await ingestLeads(rows, { store, listId: "list1" });
  assert.equal(second.inserted, 0, "re-import must add 0 new contacts");
  assert.equal(second.updated, 2, "existing contacts are updated in place");
});

