1	/**
2	 * LEAD-DB bulk loader — import a large CSV or JSON file of leads into a named
3	 * EmailList, server-side, using the SAME idempotent dedup/ingest logic as the
4	 * admin importer (lib/coldemail/import.ts + lib/coldemail/lead-store.ts). Use this
5	 * instead of the web importer for big files (tens of thousands of rows) — there's
6	 * no request timeout here.
7	 *
8	 * IDEMPOTENT: re-running the same file inserts 0 (all rows match existing and are
9	 * updated in place). DEAD/suppressed contacts are never resurrected.
10	 *
11	 * Usage:
12	 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Q3 prospects"
13	 *   npx tsx scripts/import-leads.ts --file leads.json --list-id <listId> --consent
14	 *   npx tsx scripts/import-leads.ts --file leads.csv  --list "Cold UK" --create-list
15	 *
16	 * Flags:
17	 *   --file <path>        CSV or JSON file (JSON = array of objects; keys use the
18	 *                        same header names/aliases as CSV). Required.
19	 *   --list <name>        Target list by name. Errors if ambiguous/absent unless
20	 *                        --create-list is given.
21	 *   --list-id <id>       Target list by id (takes precedence over --list).
22	 *   --create-list        Create the list (by --list name) if it doesn't exist.
23	 *   --consent            Record a LEGITIMATE_INTEREST consent row for each NEW contact.
24	 *   --dry-run            Parse + report row counts only; write nothing.
25	 *
26	 * CSV headers spec: see docs/DOCUMENTATION.md (Lead database → Import). Minimum: an
27	 * `email` column. Everything else (name, fullName, title, website, phone, city, …)
28	 * is optional and mapped through IMPORT_HEADER_ALIASES.
29	 */
30	import { readFileSync } from "node:fs";
31	import { db } from "../lib/db";
32	import {
33	  ingestLeads,
34	  parseCsv,
35	  csvToLeadRows,
36	  IMPORT_HEADER_ALIASES,
37	  type LeadRow,
38	} from "../lib/coldemail/import";
39	import { prismaLeadStore } from "../lib/coldemail/lead-store";
40	
41	function arg(name: string): string | undefined {
42	  const i = process.argv.indexOf(`--${name}`);
43	  return i !== -1 ? process.argv[i + 1] : undefined;
44	}
45	function flag(name: string): boolean {
46	  return process.argv.includes(`--${name}`);
47	}
48	
49	/** Map an arbitrary JSON object's keys onto canonical LeadRow fields via the aliases. */
50	function jsonObjToLeadRow(obj: Record<string, unknown>): LeadRow {
51	  const lead: LeadRow = {};
52	  for (const [k, v] of Object.entries(obj)) {
53	    const field = IMPORT_HEADER_ALIASES[k.trim().toLowerCase()];
54	    if (field && v != null) lead[field] = String(v).trim();
55	  }
56	  return lead;
57	}
58	
59	async function main(): Promise<void> {
60	  const filePath = arg("file");
61	  if (!filePath) {
62	    console.error("ERROR: --file <path> is required. See the header of this script for usage.");
63	    process.exit(1);
64	  }
65	
66	  const listName = arg("list");
67	  const listIdArg = arg("list-id");
68	  const createList = flag("create-list");
69	  const recordConsent = flag("consent");
70	  const dryRun = flag("dry-run");
71	
72	  // ---- Load + parse the file into LeadRow[] ----
73	  const raw = readFileSync(filePath, "utf8");
74	  let rows: LeadRow[];
75	  if (filePath.toLowerCase().endsWith(".json")) {
76	    const parsed = JSON.parse(raw);
77	    if (!Array.isArray(parsed)) throw new Error("JSON file must be an array of lead objects.");
78	    rows = parsed.map((o) => jsonObjToLeadRow(o as Record<string, unknown>));
79	  } else {
80	    const { headers, rows: csvRows } = parseCsv(raw);
81	    if (headers.length === 0) throw new Error("Could not parse a header row from the CSV.");
82	    rows = csvToLeadRows(headers, csvRows);
83	  }
84	  console.log(`Parsed ${rows.length} row(s) from ${filePath}.`);
85	
86	  if (dryRun) {
87	    console.log("--dry-run: no changes written.");
88	    await db.$disconnect();
89	    return;
90	  }
91	
92	  // ---- Resolve the target list ----
93	  let listId: string | null = null;
94	  if (listIdArg) {
95	    const list = await db.emailList.findUnique({ where: { id: listIdArg }, select: { id: true } });
96	    if (!list) throw new Error(`No list with id ${listIdArg}.`);
97	    listId = list.id;
98	  } else if (listName) {
99	    const matches = await db.emailList.findMany({ where: { name: listName }, select: { id: true } });
100	    if (matches.length === 1) listId = matches[0].id;
101	    else if (matches.length === 0) {
102	      if (!createList) throw new Error(`No list named "${listName}". Pass --create-list to create it.`);
103	      const created = await db.emailList.create({ data: { name: listName }, select: { id: true } });
104	      listId = created.id;
105	      console.log(`Created list "${listName}" (${listId}).`);
106	    } else {
107	      throw new Error(`"${listName}" is ambiguous (${matches.length} lists). Use --list-id.`);
108	    }
109	  } else {
110	    console.log("No --list/--list-id given — importing into the lead DB without list assignment.");
111	  }
112	
113	  // ---- Ingest via the shared, idempotent core ----
114	  const batch = await db.importBatch.create({
115	    data: { name: `Script import ${new Date().toISOString().slice(0, 16)}`, source: "script", listId },
116	    select: { id: true },
117	  });
118	
119	  const result = await ingestLeads(rows, {
120	    store: prismaLeadStore("script"),
121	    listId,
122	    batchId: batch.id,
123	    recordConsent,
124	    consentSource: "script import",
125	  });
126	
127	  await db.importBatch.update({
128	    where: { id: batch.id },
129	    data: {
130	      totalRows: result.totalRows,
131	      inserted: result.inserted,
132	      updated: result.updated,
133	      skippedDead: result.skippedDead,
134	      skippedDup: result.skippedDup,
135	      skippedInvalid: result.skippedInvalid,
136	    },
137	  });
138	
139	  console.log("Import complete:");
140	  console.log(`  inserted (new):          ${result.inserted}`);
141	  console.log(`  updated (existing):      ${result.updated}`);
142	  console.log(`  skipped dead/suppressed: ${result.skippedDead}`);
143	  console.log(`  skipped in-file dupes:   ${result.skippedDup}`);
144	  console.log(`  skipped invalid (no email): ${result.skippedInvalid}`);
145	  console.log(`  batch id: ${batch.id}`);
146	
147	  await db.$disconnect();
148	}
149	
150	main().catch(async (err) => {
151	  console.error("Import failed:", err?.message ?? err);
152	  await db.$disconnect().catch(() => null);
153	  process.exit(1);
154	});
