model Contact {
  id          String       @id @default(cuid())
  businessId  String
  fullName    String       @default("")
  title       String       @default("")
  email       String       @unique
  // Address-quality health. Default UNVERIFIED (LEAD-DB overhaul); legacy rows keep
  // whatever they had (UNKNOWN is treated as mailable, same as UNVERIFIED).
  emailStatus EmailStatus  @default(UNVERIFIED)
  // Overhaul Phase 1 — lead-pipeline stage (see ContactStage). Default NEW.
  stage       ContactStage @default(NEW)

  // ---- LEAD-DB overhaul: bounce / hygiene bookkeeping ----
  // `bounceCount` accumulates SOFT (transient) bounces; at the dead threshold the
  // contact flips to DEAD. `deadAt`/`deadReason` stamp the moment it left the
  // mailable pool (hard bounce, complaint, unsubscribe, or soft-bounce sunset).
  bounceCount  Int       @default(0)
  lastBounceAt DateTime?
  deadAt       DateTime?
  deadReason   String    @default("")

  // ---- LEAD-DB overhaul: engagement / campaign counters ----
  // Written by the send worker on every ColdSend that goes out, and by the reply
  // poller (`repliedAt`). Power the "emailed check-offs" columns + rollups.
  timesEmailed   Int       @default(0)
  firstEmailedAt DateTime?
  lastEmailedAt  DateTime?
  lastCampaignId String?
  repliedAt      DateTime?

  // Provenance: which bulk import created/last-touched this contact (nullable so a
  // manually-added contact simply has none).
  importBatchId String?

  createdAt DateTime @default(now())

  business       Business          @relation(fields: [businessId], references: [id], onDelete: Cascade)
  listMembers    EmailListMember[]
  consentRecords ConsentRecord[]
  sends          ColdSend[]
  conversations  Conversation[]
  importBatch    ImportBatch?      @relation(fields: [importBatchId], references: [id], onDelete: SetNull)

  @@index([businessId])
  @@index([emailStatus])
  @@index([stage])
  @@index([lastEmailedAt])
  @@index([importBatchId])
  @@index([createdAt])
}

